const test=require('node:test'), assert=require('node:assert/strict'), fs=require('node:fs'), vm=require('node:vm');
const code=fs.readFileSync('web/mood.js','utf8');
function element(){return {value:'',hidden:false,disabled:false,textContent:'',children:[],isConnected:true,style:{setProperty(){}},classList:{add(){}},setAttribute(){},append(...v){this.children.push(...v)},replaceChildren(...v){this.children=v},getBoundingClientRect(){return {left:0,top:0,width:100,height:100}}};}
function memoryStorage(saved=new Map()){return{get length(){return saved.size},key:i=>[...saved.keys()][i]??null,getItem:k=>saved.get(k)??null,setItem:(k,v)=>saved.set(k,v),removeItem:k=>saved.delete(k),saved};}
function setup(api,options={}){const elements=new Map(),host=element(),store=options.store||memoryStorage();const sessionStore=options.sessionStore||(store.sessionStore??=memoryStorage()),events={};host.querySelector=k=>{if(host.innerHTML&&!host.innerHTML.includes(k.slice(1,-1)))return null;if(!elements.has(k))elements.set(k,element());return elements.get(k)};let serial=0;const document={createElement:()=>element()},context={window:{addEventListener:(key,fn)=>events[key]=fn},document,localStorage:store,sessionStorage:sessionStore,crypto:options.crypto||(options.ledger?require('node:crypto').webcrypto:{randomUUID:()=>options.idPrefix+'op-'+(++serial)}),TextEncoder,Date,Number,String,Math,JSON,Map,Set,encodeURIComponent};context.globalThis=context;
 if(options.copy)context.window.EchoShared={copy:options.copy};vm.runInNewContext(code,context);let sid='one';const invoke=(path,opt)=>path==='/api/capabilities'?Promise.resolve({features:options.supported===false?{}:{daily_mood_entries:true,mood_self_report_suggestions:true,...(options.ledger?{mood_operation_ledger:true}:{})}}):api(path,opt);
 const widget=context.window.XinjiMood.create({api:invoke,getSessionId:()=>sid,onContext:options.onContext,surface:options.surface||'web'});widget.mount(host);host.querySelector('[data-mood-panel]').hidden=true;return{widget,host,store,sessionStore,events,find:k=>host.querySelector(`[data-mood-${k}]`),module:context.window.XinjiMood,setSid:v=>{sid=v}};}

const flush=()=>new Promise(r=>setImmediate(r));
const open=async e=>{await flush();e.find('open').onclick();await flush()};
test('quadrant maps top right to pleasant/high energy and clamps edges',()=>{const {module:m}=setup(async()=>({moods:[]}));let p=m.point(100,0,{left:0,top:0,width:100,height:100});assert.equal(p.x,1);assert.equal(p.y,1);p=m.point(-1,150,{left:0,top:0,width:100,height:100});assert.equal(p.x,-1);assert.equal(p.y,-1)});
test('two explicit axis choices and confirmation are required before saving',async()=>{const calls=[];const e=setup(async(path,opt)=>{calls.push([path,opt]);return opt?{date:path.split('/').pop(),x:0.5,y:-0.5,note:'今天',updated_at:'2026-10-30T00:00:01+00:00'}:{moods:[]}});await open(e);e.find('save').onclick();assert.equal(calls.length,1);e.find('x').oninput({target:{value:'0.5'}});e.find('save').onclick();assert.equal(calls.length,1);e.find('y').oninput({target:{value:'-0.5'}});e.find('note').value='今天';await e.find('save').onclick();const body=JSON.parse(calls[1][1].body);assert.deepEqual({...body},{session_id:'one',x:.5,y:-.5,note:'今天',confirmed:true,expected_updated_at:null});assert.match(e.find('status').textContent,/已记录/)});
test('suggestion is opt-in, partial and never persisted until both dimensions and explicit save',async()=>{const calls=[];const e=setup(async(path,opt)=>{calls.push([path,opt]);if(path==='/api/mood-suggestions')return {suggestion:{x:.6,y:null,explanation:'仅参考',evidence:['我今天很开心']}};return {moods:[]}});await open(e);e.find('source').value='我今天很开心';await e.find('analyze').onclick();assert.equal(calls.length,2);assert.equal(JSON.parse(calls[1][1].body).consent,true);const box=e.find('suggestion');assert.match(box.children[0].textContent,/并非测量/);box.children[2].onclick();assert.equal(e.find('save').disabled,true);e.find('y').oninput({target:{value:'0'}});assert.equal(e.find('save').disabled,false);assert.equal(calls.length,2)});
test('failed read blocks overwrites of existing records',async()=>{const calls=[];const e=setup(async(path,opt)=>{calls.push([path,opt]);throw Error('offline')});await open(e);e.find('x').oninput({target:{value:'0.5'}});e.find('y').oninput({target:{value:'0.5'}});e.find('save').onclick();assert.equal(calls.length,1);assert.equal(e.find('save').disabled,true);assert.match(e.find('status').textContent,/避免覆盖/)});
test('unconfirmed draft warns before reading again and keeps it if user declines',async()=>{let calls=0;const e=setup(async()=>{calls++;return {moods:[]}});await open(e);e.find('note').value='draft';e.find('note').oninput();e.find('reload').onclick();assert.equal(calls,1);assert.equal(e.find('unsaved').hidden,false);e.find('keep').onclick();assert.equal(e.find('note').value,'draft');assert.equal(calls,1);e.find('reload').onclick();e.find('discard').onclick();await flush();assert.equal(calls,2)});
test('conflict keeps draft and does not overwrite another window',async()=>{const e=setup(async(path,opt)=>{if(!opt)return {moods:[]};const x=Error('changed');x.status=409;throw x});await open(e);e.find('x').oninput({target:{value:'0.5'}});e.find('y').oninput({target:{value:'0.5'}});e.find('note').value='别丢失';await e.find('save').onclick();assert.equal(e.find('note').value,'别丢失');assert.match(e.find('status').textContent,/其他窗口已更改/)});
test('stale asynchronous responses do not change another session',async()=>{let resolve;const e=setup(()=>new Promise(r=>resolve=r));await flush();e.find('open').onclick();const before=e.find('calendar').children.length;e.widget.stop();e.setSid('two');resolve({moods:[]});await flush();assert.equal(e.find('calendar').children.length,before)});
test('closing and reopening preserves unsaved draft without another fetch',async()=>{let reads=0;const e=setup(async()=>{reads++;return {moods:[]}});await open(e);e.find('note').value='留下';e.find('note').oninput();e.find('open').onclick();e.find('open').onclick();await flush();assert.equal(reads,1);assert.equal(e.find('note').value,'留下')});
test('switching panels restores a draft with its original revision to prevent overwrite',async()=>{let revision='2026-10-30T00:00:01+00:00',sent;const e=setup(async(path,opt)=>{if(!opt)return {moods:[{date:e.module.day(new Date()),x:.1,y:.2,note:'old',updated_at:revision}]};sent=JSON.parse(opt.body);return {date:e.module.day(new Date()),x:sent.x,y:sent.y,note:sent.note,updated_at:'2026-10-30T00:00:03+00:00'}});await open(e);e.find('note').value='unsaved';e.find('note').oninput();e.widget.stop();revision='2026-10-30T00:00:02+00:00';const host=element(),elements=new Map();host.querySelector=k=>{if(host.innerHTML&&!host.innerHTML.includes(k.slice(1,-1)))return null;if(!elements.has(k))elements.set(k,element());return elements.get(k)};e.widget.mount(host);await flush();host.querySelector('[data-mood-panel]').hidden=true;host.querySelector('[data-mood-open]').onclick();await flush();assert.equal(host.querySelector('[data-mood-note]').value,'unsaved');await host.querySelector('[data-mood-save]').onclick();assert.equal(sent.expected_updated_at,'2026-10-30T00:00:01+00:00');});
test('suggestion shows exact supplied evidence as inert text',async()=>{const e=setup(async(path)=>path==='/api/mood-suggestions'?{suggestion:{x:.6,y:null,explanation:'参考',evidence:['<b>我今天很开心</b>']}}:{moods:[]});await open(e);e.find('source').value='<b>我今天很开心</b>';await e.find('analyze').onclick();assert.equal(e.find('suggestion').children[1].textContent,'依据你写的：<b>我今天很开心</b>')});
test('selecting another day prompts before discarding an unfinished note',async()=>{const e=setup(async()=>({moods:[]}));await open(e);e.find('note').value='草稿';e.find('note').oninput();const today=new Date().getDate(),other=today===1?'2':'1';const date=e.find('calendar').children.find(x=>x.textContent===other);date.onclick();assert.equal(e.find('unsaved').hidden,false);assert.equal(e.find('note').value,'草稿');e.find('discard').onclick();assert.equal(e.find('note').value,'');assert.match(e.find('date-label').textContent,new RegExp('-'+other.padStart(2,'0')+'$'))});
test('deletion requires a second click and sends the original revision',async()=>{const calls=[];const e=setup(async(path,opt)=>{calls.push([path,opt]);if(!opt)return {moods:[{date:e.module.day(new Date()),x:.1,y:.2,note:'旧记录',updated_at:'2026-10-30T12:00:00+00:00'}]};return {deleted:true}});await open(e);e.find('delete').onclick();assert.equal(calls.length,1);assert.equal(e.find('delete-confirm').hidden,false);await e.find('delete-confirm').onclick();assert.equal(calls.length,2);assert.match(calls[1][0],/expected_updated_at=2026-10-30T12%3A00%3A00%2B00%3A00/);assert.equal(calls[1][1].method,'DELETE');assert.match(e.find('status').textContent,/已删除/) });

test('map color responds continuously to both chosen axes without changing the values',()=>{const m=setup(async()=>({moods:[]})).module;assert.notEqual(m.moodTint(-1,1),m.moodTint(1,1));assert.notEqual(m.moodTint(1,-1),m.moodTint(1,1));assert.match(m.moodTint(0,0),/^rgb\(\d+, \d+, \d+\)$/)});
test('pending first read disables both text fields, controls and map until the response arrives',async()=>{let resolve;const e=setup(()=>new Promise(r=>resolve=r));await flush();e.find('open').onclick();for(const key of ['x','y','note','source','analyze','reload','prev','next'])assert.equal(e.find(key).disabled,true,key);e.find('map').onpointerdown({clientX:100,clientY:0});e.find('x').oninput({target:{value:'1'}});assert.equal(e.find('save').disabled,true);resolve({moods:[]});await flush();for(const key of ['x','y','note','source','analyze','reload','prev','next'])assert.equal(e.find(key).disabled,false,key);assert.equal(e.find('point').hidden,true)});
