test('an analysis result is discarded if its source changes before the reply',async()=>{let resolve;const e=setup(async(path)=>path==='/api/mood-suggestions'?new Promise(r=>resolve=r):{moods:[]});await open(e);e.find('source').value='我今天很开心';e.find('source').oninput();const pending=e.find('analyze').onclick();assert.equal(e.find('source').disabled,true);e.find('source').value='我现在想换一句';resolve({suggestion:{x:.6,y:null,explanation:'旧文字',evidence:['我今天很开心']}});await pending;assert.equal(e.find('source').disabled,false);assert.match(e.find('status').textContent,/已变化/);assert.equal(e.find('suggestion').children.length,0)});
