function choose(e,note='合成草稿'){e.find('x').oninput({target:{value:'.4'}});e.find('y').oninput({target:{value:'-.2'}});e.find('note').value=note;e.find('note').oninput();}
function pendingRecords(store){return [...store.saved].filter(([key])=>key.startsWith('xinji_mood_pending_')).map(([,value])=>JSON.parse(value));}
function returned(body,date,extra={}){return{date,x:body.x,y:body.y,note:body.note,updated_at:'2026-10-30T00:00:04+00:00',...extra};}
test('old capability never calls journal routes, and shared mood text is rendered at runtime',async()=>{
 const calls=[],e=setup(async(path)=>{calls.push(path);return{moods:[]}},{supported:false,copy:{'mood.title':'共享标题','mood.save':'共享保存','mood.context':'共享私密范围','mood.to_chat':'共享带入'}});await open(e);assert.equal(e.find('open').disabled,true);assert.equal(calls.length,0);assert.equal(e.find('title').textContent,'共享标题');assert.equal(e.find('save').textContent,'共享保存');assert.equal(e.find('context-note').textContent,'共享私密范围');assert.equal(e.find('context').textContent,'共享带入');
});
test('initial numeric zero is not a selection; explicitly choosing zero on both sliders permits save',async()=>{
 let writes=0;const e=setup(async(path,opt)=>{if(!opt)return{moods:[]};writes++;return returned(JSON.parse(opt.body),path.split('/').pop());});await open(e);assert.equal(e.find('point').hidden,true);assert.equal(e.find('save').disabled,true);e.find('x').oninput({target:{value:'0'}});assert.equal(e.find('save').disabled,true);e.find('y').oninput({target:{value:'0'}});assert.equal(e.find('save').disabled,false);await e.find('save').onclick();assert.equal(writes,1);
});
test('wrong-day, wrong-value, wrong-note and malformed version PUT receipts preserve the frozen draft',async()=>{
 for(const extra of [{date:'1900-01-01'},{x:-.7},{y:.8},{note:'其他内容'},{updated_at:null},{updated_at:''},{updated_at:1}]){const e=setup(async(path,opt)=>opt?returned(JSON.parse(opt.body),path.split('/').pop(),extra):{moods:[]});await open(e);choose(e);await e.find('save').onclick();assert.equal(e.find('note').value,'合成草稿');assert.equal(e.find('save').disabled,true);assert.equal(pendingRecords(e.store).length,1);assert.doesNotMatch(e.find('status').textContent,/^已记录/);}
});
