 const e=setup(async(path,opt)=>{if(!opt)return{moods:[]};throw Object.assign(Error('invalid'),{status:422})});await open(e);choose(e);await e.find('save').onclick();assert.equal(pendingRecords(e.store).length,0);assert.equal(e.find('note').value,'合成草稿');assert.equal(e.find('note').disabled,false);
