 let release;const e=setup(async(path,opt)=>opt?new Promise(resolve=>release=resolve):{moods:[]});await open(e);choose(e);const saving=e.find('save').onclick(),op=pendingRecords(e.store)[0];e.widget.stop();e.setSid('two');const later=element(),nodes=new Map();later.querySelector=k=>{if(!nodes.has(k))nodes.set(k,element());return nodes.get(k)};e.widget.mount(later);release(returned(op.body,op.date));await saving;await flush();assert.notEqual(later.querySelector('[data-mood-status]').textContent,'已记录，之后可以调整或删除。');assert.equal(later.querySelector('[data-mood-note]').value,'');
